211	    /**
212	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
213	     */
214	    @Transient
215	    public String getDisplayName() {
216	        return this.getLastName() + ", " + this.getFirstName();
217	    }
218	
219	    /**
220	     * The owner's initials: the upper-cased first letters of firstName and
221	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
222	     */
223	    @Transient
224	    public String getInitials() {
225	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
226	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
227	    }
228	
229	    /**
230	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
231	     * YY is the last two digits of the registration date's year
232	     * (e.g. {@code "NSW-A1B2C3D4-M26"}). Derived from the owner's own fields; null when
233	     * either the customer code or registration date is absent.
234	     */
235	    @Transient
236	    public String getMembershipNumber() {
237	        if (this.customerCode == null || this.registrationDate == null) {
238	            return null;
239	        }
240	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
241	    }
242	
243	    /**
244	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
245	     * contained in the {@code customerCode}, scanning right to left and doubling the
246	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
247	     * own fields; null when the customer code is absent.
248	     */
249	    @Transient
250	    public Integer getCheckDigit() {
251	        if (this.customerCode == null) {
252	            return null;
253	        }
254	        int sum = 0;
255	        boolean dbl = true;
256	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
257	            char c = this.customerCode.charAt(i);
258	            if (c < '0' || c > '9') {
259	                continue;
260	            }
261	            int d = c - '0';
262	            if (dbl) {
263	                d *= 2;
264	                if (d > 9) {
265	                    d -= 9;
266	                }
267	            }
268	            sum += d;
269	            dbl = !dbl;
270	        }
271	        return (10 - (sum % 10)) % 10;
272	    }
273	
274	    /**
275	     * The owner's membership level: a number from 1 to 4. Starts at 1, gains 1 when an
276	     * email address is present, gains a further 1 when the owner has no namesakes
277	     * ({@code namesakeCount} is 0), and gains a final 1 for tenure of more than 365 days
278	     * (the days from {@link #registrationDate} to the current date). Capped at 4. A newly
279	     * created owner has zero tenure, so these pre-tenure factors alone top out at level 3:
280	     * an owner with an email and no namesakes is level 3, not 4, until it has been
281	     * registered for over a year. Derived from the owner's own fields.
282	     */
283	    @Transient
284	    public Integer getMembershipLevel() {
285	        int level = 1;
286	        boolean hasEmail = this.email != null && !this.email.isBlank();
287	        if (hasEmail) {
288	            level++;
289	        }
290	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
291	        if (unique) {
292	            level++;
293	        }
294	        boolean tenured = this.registrationDate != null
295	            && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
296	        if (tenured) {
297	            level++;
298	        }
299	        return Math.min(level, 4);
300	    }
301	
302	    /**
303	     * Fixed city-to-region lookup table. Any city not listed derives locality
304	     * {@code "UNKNOWN"}.
305	     */
306	    private static final Map<String, String> CITY_REGION = Map.of(
307	        "Sydney", "NSW",
308	        "Melbourne", "VIC",
309	        "Brisbane", "QLD");
310	
311	    /**
312	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
313	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
314	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
315	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
316	     * postcode validation).
317	     */
318	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
319	        "NSW", new int[] {2000, 2099},
320	        "VIC", new int[] {3000, 3099},
321	        "QLD", new int[] {4000, 4099});
322	
323	    /**
324	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
325	     * Read off the {@code customerCode} prefix (the part before the first {@code '-'}) when
326	     * a customer code is present, otherwise derived straight from the postcode via
327	     * {@link #identityRegion(String)}. Either way this yields the region the customer code
328	     * was built from — NSW/VIC/QLD, or {@code "UNKNOWN"} when the postcode is absent or in
329	     * no known range. Derived from the owner's own fields.
330	     */
331	    @Transient
332	    public String getLocality() {
333	        if (this.customerCode != null) {
334	            int dash = this.customerCode.indexOf('-');
335	            if (dash > 0) {
336	                return this.customerCode.substring(0, dash);
337	            }
338	        }
339	        return identityRegion(this.postcode);
340	    }
341	
342	    /**
343	     * The REGION component of an owner's region-and-hash identity: the region derived from
344	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
345	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
346	     * of truth for the identity's region, so the {@code customerCode} prefix and the
347	     * {@link #getLocality() locality} cannot drift apart.
348	     */
349	    public static String identityRegion(String postcode) {
350	        String region = regionForPostcode(postcode);
351	        return region != null ? region : "UNKNOWN";
352	    }
353	
354	    /**
355	     * The canonical region for a city per the fixed city-to-region table
356	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
357	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
358	     * for the city-to-region mapping, used as the city's region in postcode validation.
359	     */
360	    public static String regionForCity(String city) {
361	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
362	    }
363	
364	    /**
365	     * The canonical region for a 4-digit postcode per the fixed range table
366	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
367	     * is absent, not a well-formed integer, or in no known range. Reads the shared
368	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
369	     * for the identity's region and by postcode validation to range-check a submitted
370	     * postcode against its city's region.
371	     */
372	    public static String regionForPostcode(String postcode) {
373	        if (postcode == null) {
374	            return null;
375	        }
376	        int value;
377	        try {
378	            value = Integer.parseInt(postcode.trim());
379	        } catch (NumberFormatException ex) {
380	            return null;
381	        }
382	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
383	            int[] range = entry.getValue();
384	            if (value >= range[0] && value <= range[1]) {
385	                return entry.getKey();
386	            }
387	        }
388	        return null;
389	    }
390	
391	    /**
392	     * Whether the region is subject to postcode range validation, i.e. has a known
393	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
394	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
395	     */
396	    public static boolean hasPostcodeRange(String region) {
397	        return REGION_POSTCODE_RANGES.containsKey(region);
398	    }
399	
400	    /**
401	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
402	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
403	     */
404	    @Transient
405	    public String getContactPreference() {
406	        boolean hasEmail = this.email != null && !this.email.isBlank();
407	        return hasEmail ? "EMAIL" : "PHONE";
408	    }
409	
410	    /**
411	     * The owner's identity key: a display-only composite value formed as
412	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + (householdId or empty)}.
413	     * The telephone and email are already stored in their normalized forms (E.164 and
414	     * lower-cased), and the household id is derived from the last name and postcode (empty
415	     * for an owner with no postcode). It drives no logic — duplicate detection is keyed on
416	     * the household (same last name and postcode); this value is exposed on the API purely
417	     * for reference. A null or blank part contributes an empty segment. Derived from the
418	     * owner's own fields.
419	     */
420	    @Transient
421	    public String getIdentityKey() {
422	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
423	    }
424	
425	    private static String keyPart(String value) {
426	        return (value == null || value.isBlank()) ? "" : value;
427	    }
428	
429	    /**
430	     * The stored E.164 {@link #telephone} formatted for humans: the country code,
431	     * a space, then the national digits grouped in threes (e.g.
432	     * {@code "+61 412 345 678"}). The {@code '+'} and country code are taken from the
433	     * E.164 value (a {@code '+1'} NANP country code is a single digit, any other is
434	     * treated as two digits, matching the recognized {@code '+61'}/{@code '+1'} forms),
435	     * and the national digits follow in space-separated groups of three. Returns the raw
436	     * value unchanged when it is absent or not a {@code '+'}-prefixed run of digits.
437	     * Derived from the owner's own fields; the raw {@link #telephone} stays E.164.
438	     */
439	    @Transient
440	    public String getTelephoneDisplay() {
441	        if (this.telephone == null || !this.telephone.startsWith("+")) {
442	            return this.telephone;
443	        }
444	        String digits = this.telephone.substring(1);
445	        if (!digits.matches("\\d+")) {
446	            return this.telephone;
447	        }
448	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
449	        if (digits.length() <= countryCodeLength) {
450	            return this.telephone;
451	        }
452	        String countryCode = digits.substring(0, countryCodeLength);
453	        String national = digits.substring(countryCodeLength);
454	        StringBuilder grouped = new StringBuilder();
455	        for (int i = 0; i < national.length(); i += 3) {
456	            if (grouped.length() > 0) {
457	                grouped.append(' ');
458	            }
459	            grouped.append(national, i, Math.min(i + 3, national.length()));
460	        }
461	        return "+" + countryCode + " " + grouped;
462	    }
463	
464	    protected Set<Pet> getPetsInternal() {
465	        if (this.pets == null) {
466	            this.pets = new HashSet<>();
467	        }
468	        return this.pets;
469	    }
470	
471	    protected void setPetsInternal(Set<Pet> pets) {
472	        this.pets = pets;
473	    }
474	
475	    public List<Pet> getPets() {
476	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
477	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
478	        return Collections.unmodifiableList(sortedPets);
479	    }
480	
481	    public void setPets(List<Pet> pets) {
482	        this.pets = new HashSet<>(pets);
483	    }
484	
485	    public void addPet(Pet pet) {
486	        getPetsInternal().add(pet);
487	        pet.setOwner(this);
488	    }
489	
490	    /**
491	     * Return the Pet with the given name, or null if none found for this Owner.
492	     *
493	     * @param name to test
494	     * @return true if pet name is already in use
495	     */
496	    public Pet getPet(String name) {
497	        return getPet(name, false);
498	    }
499	
500	    /**
501	     * Return the Pet with the given name, or null if none found for this Owner.
502	     *
503	     * @param name to test
504	     * @return true if pet name is already in use
505	     */
506	    public Pet getPet(String name, boolean ignoreNew) {
507	        name = name.toLowerCase();
508	        for (Pet pet : getPetsInternal()) {
509	            if (!ignoreNew || !pet.isNew()) {
510	                String compName = pet.getName();
511	                compName = compName.toLowerCase();
512	                if (compName.equals(name)) {
513	                    return pet;
514	                }
515	            }
516	        }
517	        return null;
518	    }
519	
520	    public Pet getPet(Integer petId) {
521	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
522	    }
523	
524	    @Override
525	    public String toString() {
526	        return new ToStringCreator(this)
527	
528	            .append("id", this.getId())
529	            .append("new", this.isNew())
530	            .append("lastName", this.getLastName())
531	            .append("firstName", this.getFirstName())
532	            .append("address", this.address)
533	            .append("city", this.city)
534	            .append("telephone", this.telephone)
535	            .append("email", this.email)
536	            .toString();
537	    }
538	}
